sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float scale;
uniform float speed;
uniform float intensity;
uniform float sharpness;
uniform float refraction;
layout(color) uniform half4 tint;
uniform float blend;
uniform float opacity;
float4 tex(float2 p) {
    return float4(image.eval(clamp(p, float2(0.0), size)));
}
float3 unp(float4 c) {
    return c.rgb / max(c.a, 0.0001);
}
float luma(float3 c) {
    return dot(c, float3(0.2126, 0.7152, 0.0722));
}
half4 fin(float4 o, float4 r, float op) {
    return half4(mix(o, r, saturate(op)));
}
float hash21(float2 p) {
    return fract(sin(dot(p, float2(127.1, 311.7))) * 43758.5453);
}
float vnoise(float2 p) {
    float2 i = floor(p);
    float2 f = fract(p);
    f = f * f * (3.0 - 2.0 * f);
    float a = hash21(i);
    float b = hash21(i + float2(1.0, 0.0));
    float c = hash21(i + float2(0.0, 1.0));
    float d = hash21(i + float2(1.0, 1.0));
    return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}
float3 blendm(float3 b, float3 s, float m) {
    if (m < 0.5) return s;
    if (m < 1.5) return b + s;
    if (m < 2.5) return 1.0 - (1.0 - b) * (1.0 - s);
    if (m < 3.5) return b * s;
    if (m < 4.5) return mix(2.0 * b * s, 1.0 - 2.0 * (1.0 - b) * (1.0 - s), step(float3(0.5), b));
    if (m < 5.5) return (1.0 - 2.0 * s) * b * b + 2.0 * s * b;
    if (m < 6.5) return max(b, s);
    if (m < 7.5) return min(b, s);
    if (m < 8.5) return abs(b - s);
    return b / max(1.0 - s, 0.001);
}
half4 main(float2 coord) {
    float2 p = coord / max(scale, 1.0);
    float t = time * speed;
    float v = 0.0;
    float2 dsp = float2(0.0);
    for (int i = 0; i < 3; i++) {
        float fi = float(i);
        float2 q = p * (1.0 + fi * 0.7) + float2(t * (0.4 + fi * 0.2), -t * 0.3 * (fi + 1.0));
        float n = vnoise(q * 2.0 + vnoise(q * 3.0 + t) * 2.0);
        v += pow(1.0 - abs(2.0 * n - 1.0), mix(2.0, 12.0, sharpness));
        dsp += float2(vnoise(q + 3.1), vnoise(q - 5.7)) - 0.5;
    }
    v = v / 3.0;
    float4 c = tex(coord);
    float4 r = tex(coord + dsp * refraction);
    float3 s = unp(r);
    float3 layer = float3(tint.rgb) * v * intensity;
    float3 o = blendm(s, layer, blend);
    return fin(c, float4(max(o, float3(0.0)) * r.a, r.a), opacity);
}
